package dev.pocketengine.features.plugins;

import static org.junit.Assert.*;
import android.app.Application;
import android.database.sqlite.SQLiteDatabase;
import dev.pocketengine.core.RunControl;
import dev.pocketengine.features.FeatureContext;
import dev.pocketengine.features.local.LocalModule;
import dev.pocketengine.features.local.project.ProjectSources;
import dev.pocketengine.features.local.runtime.*;
import dev.pocketengine.features.workspace.WorkspaceModule;
import dev.pocketengine.store.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
import org.json.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.RuntimeEnvironment;
import org.robolectric.annotation.Config;
import org.robolectric.annotation.SQLiteMode;

/** Actual installed host runtime, real original checkout and native SQLite approval/operation.
 * No child process is launched by these review/admission tests; the native pipeline is separate. */
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=Application.class)
@SQLiteMode(SQLiteMode.Mode.NATIVE)
public final class McpLocalDiscoveryReviewTest {
    static final class Fixture implements AutoCloseable {
        final Application android=RuntimeEnvironment.getApplication();final FeatureContext context=new FeatureContext(android,new SettingsStore(android),new SecretVault(android),event->{});final TaskStore tasks;final WorkspaceModule workspace=new WorkspaceModule(context);final PluginsModule plugins=new PluginsModule(context);final ManagedProjectRuntime runtime;final LocalModule local;final String project,checkout;final Path root=Files.createTempDirectory("pw-mcp-review-owned-");final dev.pocketengine.features.local.runtime.RuntimeEnvironment.Package pack;final JSONObject config;
        Fixture()throws Exception{this("python3","server.py","raise AssertionError('review must not execute source')\n");}
        Fixture(String executable,String entry,String program)throws Exception{
            android.deleteDatabase("pocket-world.db");tasks=new TaskStore(android);byte[] marker="own marker only; no third-party interpreter redistribution".getBytes(java.nio.charset.StandardCharsets.UTF_8);ByteArrayOutputStream zipped=new ByteArrayOutputStream();try(ZipOutputStream out=new ZipOutputStream(zipped)){out.putNextEntry(new ZipEntry("share/marker"));out.write(marker);out.closeEntry();}byte[] archive=zipped.toByteArray();
            pack=new dev.pocketengine.features.local.runtime.RuntimeEnvironment.Package(new JSONObject().put("id","mcp-review-owned-fixture").put("revision","1").put("license","CC0-1.0 own marker, host interpreter not redistributed").put("abi","host-only").put("archiveSha256",ProjectSources.sha256(archive)).put("archiveBytes",archive.length).put("files",new JSONArray().put(new JSONObject().put("path","share/marker").put("bytes",marker.length).put("sha256",ProjectSources.sha256(marker)))));
            File python=new File(Objects.requireNonNull(System.getProperty("a25.python"))).getCanonicalFile(),shell=new File("/bin/sh").getCanonicalFile();Map<String,RuntimeTool> tools=new HashMap<>(Map.of("python3",tool("python3",python),"sh",tool("sh",shell)));if(executable.equals("node"))tools.put("node",tool("node",new File(Objects.requireNonNull(System.getProperty("a25.node"))).getCanonicalFile()));runtime=ManagedProjectRuntime.create(root.toFile(),pack,tools);runtime.environmentManager().install(pack,new ByteArrayInputStream(archive),()->{},(phase,done,total)->{});local=new LocalModule(context,workspace,runtime);
            project=workspace.handle("create",new JSONObject().put("name","Original MCP owner source")).getString("id");workspace.handle("write",new JSONObject().put("projectId",project).put("path",entry).put("expectedVersion",0).put("content",program));checkout=local.handle("prepare",new JSONObject().put("projectId",project)).getString("id");config=new JSONObject().put("id","local_probe").put("name","本机确切程序").put("checkoutId",checkout).put("expectedSourceDigest",digest()).put("executable",executable).put("argv",new JSONArray().put(entry).put("--public-mode").put("fixture"));
        }
        static RuntimeTool tool(String name,File file)throws Exception{return new RuntimeTool(name,file,ProjectSources.sha256(Files.readAllBytes(file.toPath())),"actual host fixture","host binary not redistributed",List.of(),List.of("--version"));}
        String digest()throws Exception{return local.describeMcpWorkspaceForOwner(checkout,new RunControl()).getString("sourceDigest");}
        McpLocalDiscovery.Review review()throws Exception{return local.reviewMcpForOwner(new JSONObject(config.toString()),new RunControl()).bindPluginTarget(plugins);}
        McpLocalDiscovery.Confirmed confirmed()throws Exception{McpLocalDiscovery.Review review=review();return review.confirm(review.metadata().getString("planDigest"));}
        JSONObject installEcho()throws Exception{return plugins.handle("install",new JSONObject().put("manifest",new JSONObject().put("id","local_probe").put("name","Original declared plugin").put("version","1").put("tools",new JSONArray().put(new JSONObject().put("name","echo").put("kind","echo")))).put("expectedInstallationId",""));}
        RuntimeInvocation boundInvocation(McpLocalDiscovery.Confirmed confirmed,RunControl control)throws Exception{tasks.beginOwnerMcpDiscoveryForOwner(confirmed,control);RuntimeInvocation invocation=confirmed.invocationForHost(tasks,control,()->{tasks.requireOwnerMcpDiscoveryCurrentForOwner(confirmed.actionId(),control);confirmed.requireCurrentForHost(tasks,control);});JSONObject binding=NativePipeAdmission.bindingForHost(McpLocalDiscovery.pipeIdentityForHost(confirmed.scope()),invocation.binding(),invocation.executionRef().sourceDigest(),McpLocalDiscovery.WRITE_BYTE_LIMIT);tasks.bindOwnerMcpDiscoveryJobForHost(confirmed,invocation,binding,control);return invocation;}
        @Override public void close()throws Exception{local.close();plugins.close();workspace.close();var field=TaskStore.class.getDeclaredField("db");field.setAccessible(true);((SQLiteDatabase)field.get(tasks)).close();try(var paths=Files.walk(root)){for(Path p:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(p);}}
    }
    @Test public void nativeReviewShowsExactProgramAndSameUidRiskButStartsNoTaskOrProcess()throws Exception{try(Fixture f=new Fixture();McpLocalDiscovery.Review review=f.review()){JSONObject view=review.metadata();assertEquals(f.checkout,view.getString("checkoutId"));assertEquals("server.py",view.getJSONArray("argv").getString(0));assertTrue(view.getString("risk").contains("同UID"));assertFalse(view.getBoolean("osSandbox"));assertFalse(view.getBoolean("executionAuthorized"));assertFalse(view.getBoolean("installationAuthorized"));assertFalse(view.getBoolean("toolInvocationAuthorized"));assertEquals("",view.getString("expectedInstallationId"));assertTrue(view.isNull("expectedStateRevision"));assertEquals(0,f.tasks.list().length());assertEquals(0,f.runtime.environmentManager().describe(f.pack).getInt("activeLeases"));}}
    @Test public void onlyTheDisplayedPlanDigestCanConsumeThePrivateNativeConfirmation()throws Exception{try(Fixture f=new Fixture();McpLocalDiscovery.Review review=f.review()){String digest=review.metadata().getString("planDigest");assertThrows(SecurityException.class,()->review.confirm("0".repeat(64)));McpLocalDiscovery.Confirmed confirmed=review.confirm(digest);assertThrows(SecurityException.class,()->review.confirm(digest));assertEquals(digest,confirmed.scope().getString("planDigest"));assertFalse(confirmed.scope().has("argv"));confirmed.close();}}
    @Test public void aReviewWithoutOriginalPluginAbsentOrInstallationCasCannotConfirm()throws Exception{try(Fixture f=new Fixture();McpLocalDiscovery.Review review=f.local.reviewMcpForOwner(f.config,new RunControl())){assertThrows(SecurityException.class,review::metadata);assertThrows(SecurityException.class,()->review.confirm("0".repeat(64)));assertEquals(0,f.tasks.list().length());}}
    @Test public void approvedFactoryCreatesOneRealOriginalRunOperationAndNoInferenceOrToolAllowance()throws Exception{try(Fixture f=new Fixture()){McpLocalDiscovery.Confirmed confirmed=f.confirmed();RunControl original=new RunControl();JSONObject first=f.tasks.beginOwnerMcpDiscoveryForOwner(confirmed,original);assertFalse(first.getBoolean("knownOperation"));assertTrue(original.matchesHostRun(confirmed.actionId(),confirmed.actionId(),1));assertEquals(1,f.tasks.list().length());JSONObject task=f.tasks.get(confirmed.actionId(),false);assertEquals("tool",task.getString("kind"));assertEquals(1,task.getJSONArray("operations").length());assertFalse(first.getBoolean("agentRunnerCreated"));f.tasks.requireOwnerMcpDiscoveryCurrentForOwner(confirmed.actionId(),original);RunControl unrelated=new RunControl();assertTrue(f.tasks.beginOwnerMcpDiscoveryForOwner(confirmed,unrelated).getBoolean("knownOperation"));assertFalse(unrelated.hasHostRun());assertEquals(1,f.tasks.list().length());assertThrows(SecurityException.class,()->f.tasks.startAttempt(confirmed.actionId(),"capabilities",10));}}
    @Test public void changedActualSourceCannotEnterTaskFactoryAfterTheNativeReview()throws Exception{try(Fixture f=new Fixture()){McpLocalDiscovery.Confirmed confirmed=f.confirmed();Path actual=f.android.getFilesDir().toPath().resolve("local-development/checkouts").resolve(f.checkout).resolve("files/server.py");Files.write(actual,"print('changed')\n".getBytes(java.nio.charset.StandardCharsets.UTF_8));assertThrows(SecurityException.class,()->f.tasks.beginOwnerMcpDiscoveryForOwner(confirmed,new RunControl()));assertEquals(0,f.tasks.list().length());}}
    @Test public void absentRaceOrInstalledRevisionChangeRejectsTheOldNativeReview()throws Exception{try(Fixture f=new Fixture()){McpLocalDiscovery.Confirmed absent=f.confirmed();JSONObject installed=f.installEcho();assertThrows(SecurityException.class,()->f.tasks.beginOwnerMcpDiscoveryForOwner(absent,new RunControl()));try(McpLocalDiscovery.Review review=f.review()){JSONObject view=review.metadata();assertEquals(installed.getString("installationId"),view.getString("expectedInstallationId"));assertEquals(0,view.getLong("expectedStateRevision"));McpLocalDiscovery.Confirmed current=review.confirm(view.getString("planDigest"));f.plugins.setEnabledReviewed("local_probe",installed.getString("installationId"),true);assertThrows(SecurityException.class,()->f.tasks.beginOwnerMcpDiscoveryForOwner(current,new RunControl()));assertEquals(0,f.tasks.list().length());}}}
    @Test public void shellEvalEnvironmentSecretsAndMissingOrHostEntryPathsAreRefusedBeforeAnyTask()throws Exception{try(Fixture f=new Fixture()){for(JSONObject bad:new JSONObject[]{new JSONObject(f.config.toString()).put("executable","sh"),new JSONObject(f.config.toString()).put("argv",new JSONArray().put("-c").put("arbitrary")),new JSONObject(f.config.toString()).put("argv",new JSONArray().put("server.py").put("--token=never-store")),new JSONObject(f.config.toString()).put("env",new JSONObject().put("API_TOKEN","never-store")),new JSONObject(f.config.toString()).put("argv",new JSONArray().put("/tmp/host.py")),new JSONObject(f.config.toString()).put("argv",new JSONArray().put("missing.py")),new JSONObject(f.config.toString()).put("workingDirectory","subdir")})assertThrows(Exception.class,()->f.local.reviewMcpForOwner(bad,new RunControl()));assertEquals(0,f.tasks.list().length());assertEquals(0,f.runtime.environmentManager().describe(f.pack).getInt("activeLeases"));}}
    @Test public void originalModelControlAndCancelledNativeReviewCannotMintAnOwnerApproval()throws Exception{try(Fixture f=new Fixture()){RunControl model=new RunControl();model.bindHostRun("fixture-task","fixture-run",1);assertThrows(SecurityException.class,()->f.local.reviewMcpForOwner(f.config,model));RunControl reviewControl=new RunControl();McpLocalDiscovery.Review review=f.local.reviewMcpForOwner(f.config,reviewControl).bindPluginTarget(f.plugins);String digest=review.metadata().getString("planDigest");reviewControl.cancel();assertThrows(Exception.class,()->review.confirm(digest));assertEquals(0,f.tasks.list().length());}}
    @Test public void dispatchFenceBindsTheExactRealRefOnceBeforeAnyNativeChildExists()throws Exception{try(Fixture f=new Fixture()){McpLocalDiscovery.Confirmed confirmed=f.confirmed();RunControl original=new RunControl();RuntimeInvocation invocation=f.boundInvocation(confirmed,original);JSONObject stored=f.tasks.ownerMcpDiscoveryForOwner(confirmed.actionId());assertEquals("unknown",stored.getString("operationState"));assertEquals(invocation.executionRef().operationId(),stored.getJSONObject("nativeJob").getJSONObject("binding").getString("operationId"));assertEquals(McpLocalDiscovery.INTENT,stored.getJSONObject("nativeJob").getJSONObject("exact").getString("intent"));assertEquals("absent",stored.getJSONObject("nativeJob").getJSONObject("nativePipeBinding").getString("expectedInstallationId"));assertEquals(0,f.runtime.environmentManager().describe(f.pack).getInt("activeLeases"));assertThrows(SecurityException.class,()->f.tasks.bindOwnerMcpDiscoveryJobForHost(confirmed,invocation,stored.getJSONObject("nativeJob").getJSONObject("nativePipeBinding"),original));}}
    @Test public void callerCannotSubstituteAnInvokePurposeForTheOwnerDiscoveryFence()throws Exception{try(Fixture f=new Fixture()){McpLocalDiscovery.Confirmed confirmed=f.confirmed();RunControl original=new RunControl();f.tasks.beginOwnerMcpDiscoveryForOwner(confirmed,original);RuntimeInvocation invocation=confirmed.invocationForHost(f.tasks,original,()->{});JSONObject wrong=NativePipeAdmission.bindingForHost(McpLocalDiscovery.pipeIdentityForHost(confirmed.scope()),invocation.binding(),invocation.executionRef().sourceDigest(),McpLocalDiscovery.WRITE_BYTE_LIMIT).put("purpose",NativePipeAdmission.INVOKE);assertThrows(SecurityException.class,()->f.tasks.bindOwnerMcpDiscoveryJobForHost(confirmed,invocation,wrong,original));assertNull(f.tasks.ownerMcpDiscoveryForOwner(confirmed.actionId()).optJSONObject("nativeJob"));}}
    @Test public void lateProcessOnlyObservationAfterCancelCannotBecomeCompletedOrReplayAuthority()throws Exception{try(Fixture f=new Fixture()){McpLocalDiscovery.Confirmed confirmed=f.confirmed();RunControl original=new RunControl();RuntimeInvocation invocation=f.boundInvocation(confirmed,original);f.tasks.cancelOwnerMcpDiscoveryForOwner(confirmed.actionId());original.cancel();assertThrows(Exception.class,()->f.tasks.requireOwnerMcpDiscoveryCurrentForOwner(confirmed.actionId(),original));JSONObject unknown=new JSONObject().put("id",confirmed.actionId()).put("operationId",confirmed.actionId()).put("checkoutId",f.checkout).put("projectExecution",invocation.executionRef().executionLink()).put("sourceDigest",invocation.executionRef().sourceDigest()).put("status","unknown").put("receiptReceived",false).put("resourcesReleased",false).put("processExited",false).put("argumentValuesIncluded",false).put("argvCount",confirmed.scope().getInt("argvCount")).put("argvDigest",confirmed.scope().getString("argvDigest"));RuntimeReceipt receipt=RuntimeReceipt.fromBackend(invocation.executionRef(),unknown);McpLocalDiscovery.Observation observed=McpLocalDiscovery.observeForHost(confirmed.scope(),receipt);f.tasks.recordOwnerMcpDiscoveryForHost(observed);assertFalse(observed.outcomeSettled());assertFalse(observed.publicSummary().has("argv"));assertFalse(f.tasks.ownerMcpDiscoveryForOwner(confirmed.actionId()).getString("status").equals("completed"));assertTrue(f.tasks.hasUnresolved(confirmed.actionId()));}}
    @Test public void visibleManifestNeverReadsHiddenBytesOrTreatsThemAsAWholeCheckoutVersion()throws Exception{try(Fixture f=new Fixture()){Path source=f.android.getFilesDir().toPath().resolve("local-development/checkouts").resolve(f.checkout).resolve("files"),hidden=source.resolve(".env");Files.write(hidden,"OWN_LOW_ENTROPY_SECRET_NOT_SELECTED".getBytes(java.nio.charset.StandardCharsets.UTF_8));var old=Files.getPosixFilePermissions(hidden);try{Files.setPosixFilePermissions(hidden,java.util.Set.of());JSONObject view=f.local.describeMcpWorkspaceForOwner(f.checkout,new RunControl());assertEquals(f.config.getString("expectedSourceDigest"),view.getString("sourceDigest"));assertEquals(1,view.getJSONArray("files").length());assertFalse(view.toString().contains(".env"));assertFalse(view.toString().contains("OWN_LOW_ENTROPY"));assertFalse(view.getBoolean("wholeCheckoutVersion"));assertFalse(view.getBoolean("hiddenFilesIncluded"));assertFalse(view.getBoolean("sourceBodyIncluded"));}finally{Files.setPosixFilePermissions(hidden,old);}}}
    @Test public void copiedInvocationUsesActualPerOperationBytesNotTheOriginalCwdOrHiddenConfig()throws Exception{try(Fixture f=new Fixture()){Path source=f.android.getFilesDir().toPath().resolve("local-development/checkouts").resolve(f.checkout).resolve("files");Files.write(source.resolve(".env"),"OWN_NOT_COPIED".getBytes(java.nio.charset.StandardCharsets.UTF_8));Files.createDirectories(source.resolve("node_modules"));Files.write(source.resolve("node_modules/never.js"),new byte[]{1,2,3});McpLocalDiscovery.Confirmed confirmed=f.confirmed();RunControl control=new RunControl();RuntimeInvocation invocation=f.boundInvocation(confirmed,control);Path copy=invocation.workspace().directory().toPath();assertNotEquals(source,copy);assertEquals(confirmed.actionId(),copy.getFileName().toString());assertTrue(Files.exists(copy.resolve("server.py")));assertFalse(Files.exists(copy.resolve(".env")));assertFalse(Files.exists(copy.resolve("node_modules")));assertArrayEquals(Files.readAllBytes(source.resolve("server.py")),Files.readAllBytes(copy.resolve("server.py")));assertEquals(confirmed.actionId(),invocation.exact().getJSONObject("payload").getString("nativeMcpExecutionCopyId"));assertEquals("per_operation_visible_copy",confirmed.scope().getString("executionWorkspace"));assertFalse(confirmed.scope().getBoolean("osSandbox"));}}

}
